	@Test
	void textSourceTotalsDoNotCountAccessSiteBreakdownsTwice() {
		try (var ignored = QueryExplanationContext.enter(Explanation.Level.Telemetry)) {
			SingletonSet target = target(true);
			NativeSlotLayout layout = new NativeSlotLayout(Map.of("root", 0), null);
			layout.freeze(List.of("root"));
			var invocation = LmdbNativeExplain.recordRuntimeEntryPlan(target, SingletonPlan.INSTANCE, layout, 1L);
			invocation.adjacencyAccessAt("first-pattern").measurement(true, 100L, 3L, 97L, false, true);
			invocation.adjacencyAccessAt("second-pattern").measurement(false, 7L, 7L, 0L, false, false);
			invocation.complete();

			String text = target.getStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN);
			for (var expected : Map.of("rowsScannedActual", 107L, "rowsMatchedActual", 10L,
					"rowsFilteredActual", 97L).entrySet()) {
				long total = Pattern.compile("(?m)^\\s*" + expected.getKey() + ": ([0-9][0-9,]*)\\s*$")
						.matcher(text)
						.results()
						.mapToLong(match -> Long.parseLong(match.group(1).replace(",", "")))
						.sum();
				assertThat(total).as("legacy aggregate %s must exclude the site breakdown", expected.getKey())
						.isEqualTo(expected.getValue());
			}
			assertThat(text).contains("siteRowsScannedActual: 100", "siteRowsScannedActual: 7");
			assertThat(QueryExplanationContext.telemetry().snapshot().stages())
					.filteredOn(stage -> "Statement access".equals(stage.operator()))
					.extracting(stage -> stage.metrics().get("rowsScanned").count())
					.containsExactlyInAnyOrder(100L, 7L);
		}
	}

	@Test
	void filterFeedbackDoesNotInventUnmeasuredOperatorTime() {
		try (var explanation = QueryExplanationContext.enter(Explanation.Level.Telemetry);
				var feedback = LmdbFusedSipFactorizedRuntime.enter(23L)) {
			SingletonSet target = target(true);
			NativeSlotLayout layout = new NativeSlotLayout(Map.of("root", 0), null);
			layout.freeze(List.of("root"));
			var invocation = LmdbNativeExplain.recordRuntimeEntryPlan(target, SingletonPlan.INSTANCE, layout, 1L);
			feedback.session().observeFilter(1, "untimed", 0, 0, 10L, 4L, 0L, 6L);
			feedback.session().observeFilter(2, "some timed feedback", 0, 0, 3L, 2L, 123L, 1L);
			invocation.fusedTelemetry(feedback.session().telemetry());
			invocation.complete();
			var stages = QueryExplanationContext.telemetry().snapshot().stages();
			assertThat(stages).filteredOn(stage -> "untimed".equals(stage.properties().get("expression")))
					.singleElement()
					.satisfies(stage -> {
						assertThat(stage.metrics().get("tests").count()).isEqualTo(10L);
						assertThat(stage.metrics().get("elapsedTime").count()).isNull();
						assertThat(stage.metrics().get("elapsedTime").origin()).isEqualTo("unavailable");
					});
			assertThat(stages)
					.filteredOn(stage -> "some timed feedback".equals(stage.properties().get("expression")))
					.singleElement()
					.satisfies(stage -> {
						assertThat(stage.metrics().get("elapsedTime").count()).isEqualTo(123L);
						assertThat(stage.metrics().get("elapsedTime").state()).isEqualTo("partial");
						assertThat(stage.metrics().get("elapsedTime").scope()).contains("feedback observations");
					});
		}
	}

	@Test
	void reusedAlgebraGetsFreshQueryScopedPhysicalSources() throws IOException {
		SingletonSet target = target(true);
		NativeSlotLayout layout = new NativeSlotLayout(Map.of("root", 0), null);
		layout.freeze(List.of("root"));
		for (int query = 0; query < 2; query++) {
			try (var ignored = QueryExplanationContext.enter(Explanation.Level.Telemetry)) {
				var candidate = candidate("query" + query, 1D, () -> "answer");
				new LmdbNativeDispatchLoop<>(LmdbNativeDecisionPoint.ROW, List.of(strategy(candidate)), target)
						.eager()
						.dispatch(null);
				var invocation = LmdbNativeExplain.recordRuntimeEntryPlan(target, SingletonPlan.INSTANCE, layout, 1L);
				invocation.adjacencyAccessAt("pattern").measurement(true, 7L, 2L, 5L, false, true, 123L, "spoc");
				invocation.complete();
				QueryExecutionProfile profile = QueryExplanationContext.telemetry().snapshot();
				assertThat(profile.attempts()).hasSize(1);
				assertThat(profile.attempts().getFirst().strategy()).isEqualTo("query" + query);
				assertThat(profile.stages()).filteredOn(stage -> stage.operator().equals("Statement access"))
						.singleElement()
						.satisfies(stage -> {
							assertThat(stage.metrics().get("rowsScanned").count()).isEqualTo(7L);
							assertThat(stage.metrics().get("activeTime").count()).isEqualTo(123L);
							assertThat(stage.properties()).containsEntry("index", "spoc");
						});
			}
		}
	}

	@Test
	void sampledEarlyCloseIsPartialAndPreservesObservedWork() throws IOException {
		try (var ignored = QueryExplanationContext.enter(Explanation.Level.Telemetry)) {
			SingletonSet target = target(true);
			var selected = new LmdbNativeDispatchLoop<>(LmdbNativeDecisionPoint.ROW,
					List.of(strategy(candidate("stream", 1D, () -> "answer"))), target).dispatch(null);
			var observation = selected.observation();
			for (int pull = 0; pull < 100; pull++) {
				long started = observation.beginPull();
				observation.endPull(started);
				observation.rows(1);
			}
			observation.closed();
			var attempt = QueryExplanationContext.telemetry().snapshot().attempts().getFirst();
			assertThat(attempt.status()).isEqualTo("EARLY_CLOSED");
			assertThat(attempt.metrics().get("activeTime").origin()).isEqualTo("sampled");
			assertThat(attempt.metrics().get("activeTime").state()).isEqualTo("partial");
			assertThat(attempt.metrics().get("producerRows").count()).isEqualTo(100L);
			assertThat(attempt.metrics().get("producerRows").state()).isEqualTo("partial");
			assertThat(attempt.metrics()).doesNotContainKey("predictionError");
		}
	}

	@Test
	void anAdmissionDeclineRetainsItsReasonWithoutClaimingExecutedWork() throws IOException {
		try (var ignored = QueryExplanationContext.enter(Explanation.Level.Telemetry)) {
			SingletonSet target = target(true);
			LmdbNativeStrategy<Void, String> unavailable = LmdbNativeStrategy.of(LmdbNativeDecisionPoint.ROW,
					"native", context -> LmdbNativeAdmission.declined("UNSUPPORTED_GRAPH_SCOPE"));
			assertThat(new LmdbNativeDispatchLoop<>(LmdbNativeDecisionPoint.ROW, List.of(unavailable), target)
					.dispatch(null)).isNull();
			assertThat(QueryExplanationContext.telemetry().snapshot().attempts()).singleElement().satisfies(attempt -> {
				assertThat(attempt.status()).isEqualTo("NOT_ADMITTED");
				assertThat(attempt.reason()).contains("UNSUPPORTED_GRAPH_SCOPE");
				assertThat(attempt.elapsedNanos()).isNull();
			});
		}
	}

