	@Test
	void failedOpenRemainsVisibleAfterAnotherCandidateSucceeds() throws IOException {
		SingletonSet target = target(true);
		LmdbNativeCandidate<String> refused = candidate("refused", 1D, () -> {
			throw new KernelRuntime.AllocationDeniedException();
		});
		LmdbNativeCandidate<String> fallback = candidate("fallback", 100D, () -> "answer");
		var selection = new LmdbNativeDispatchLoop<>(LmdbNativeDecisionPoint.ROW,
				List.of(strategy(refused), strategy(fallback)), target).eager().budgetRefusals(true).dispatch(null);

		assertThat(selection.value()).isEqualTo("answer");
		assertThat(target.getLongMetricActual("nativeAttemptsActual")).isEqualTo(2L);
		assertThat(target.getLongMetricActual("nativeDiscardedAttemptsActual")).isEqualTo(1L);
		assertThat(target.getStringMetricActual("nativeAttemptLedger"))
				.contains("refused", "BUDGET_REFUSED", "fallback", "COMPLETED");
	}

